def mark_existing_advances(apps, schema_editor):
    """Receipts recorded with "Nouvelle avance" before is_advance existed:
    advance mode posts a single invoice-less allocation, so a receipt whose
    allocations all still point at no invoice is an advance (an ordinary
    payment always carries at least one invoice line)."""
    CustomerPayment = apps.get_model("finance", "CustomerPayment")
    for payment in CustomerPayment.objects.filter(is_indirect=False).prefetch_related("allocations"):
        allocations = list(payment.allocations.all())
        if allocations and all(a.invoice_id is None for a in allocations):
            payment.is_advance = True
            payment.save(update_fields=["is_advance"])


Migration.operations.append(migrations.RunPython(mark_existing_advances, migrations.RunPython.noop))
